<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

trait ThemeTenantAttributeHolder
{
    protected ThemeTenantVO|TenantRef|null $tenant = null;
    protected bool $tenantAssigned = false;

    public function getTenantOrCurrent(?ThemeTenantVO $tenant): ?ThemeTenantVO
    {
        return $this->tenantAssigned ? ($this->tenant === null ? null : ThemeTenantVO::from($this->tenant)) : $tenant;
    }
    public function tenantTryBuildInitial(ConstraintFailList $error): ?ThemeTenantVO
    {
        return  ThemeTenantVO::tryFrom($this->tenantAssigned ? $this->tenant : null, $error);
    }
    public function tenant(ThemeTenantVO|TenantRef|null $tenant): static
    {
        $this->tenant = $tenant;
        $this->tenantAssigned = true;
        return $this;
    }
    public function getTenant(): ?TenantRef
    {
        return $this->tenant instanceof ThemeTenantVO ? $this->tenant->value() : $this->tenant;
    }
    public function isTenantAssigned(): bool
    {
        return $this->tenantAssigned;
    }
    public function writeTenantTo(mixed $att): void
    {
        if ($this->tenantAssigned) {
            $att->tenant($this->tenant);
        }
    }
    public function readTenantFrom(mixed $att): void
    {
        if ($att->isTenantAssigned()) {
            $tenant = $att->getTenant();
            $this->tenant($tenant);
        }
    }
    public function unsetTenant(): static
    {
        $this->tenantAssigned = false;
        return $this;
    }
    protected function withDefaultTenant(): void
    {
    }
    protected function withAssertedTenantRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->tenantAssigned = $this->tenantAssigned) {
            $value->tenant = ThemeTenantVO::tryFrom($this->tenant, $errorsList);
        }
    }
}
